package com.companages.service;
import com.companages.dto.AssignmentDtos.*; import com.companages.entity.*; import com.companages.exception.*; import com.companages.repository.AssignmentRepository; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.List;
@Service public class AssignmentService { private final AssignmentRepository assignments; private final OrganizationService organizations; private final MemberService members; private final PositionService positions; public AssignmentService(AssignmentRepository a,OrganizationService o,MemberService m,PositionService p){assignments=a;organizations=o;members=m;positions=p;}
 @Transactional public Response create(Long oid,CreateRequest r){Organization o=organizations.require(oid);Member m=members.require(oid,r.memberId());Position p=positions.require(oid,r.positionId());if(assignments.existsByMemberIdAndPositionId(m.getId(),p.getId()))throw new BusinessException("Member already has this position");Assignment a=new Assignment();a.setOrganization(o);a.setMember(m);a.setPosition(p);return Mappers.assignment(assignments.save(a));}
 @Transactional(readOnly=true) public List<Response> list(Long oid){organizations.require(oid);return assignments.findAllByOrganizationIdOrderByCreatedAtDesc(oid).stream().map(Mappers::assignment).toList();}
 @Transactional public void delete(Long oid,Long id){organizations.require(oid);Assignment a=assignments.findByIdAndOrganizationId(id,oid).orElseThrow(()->new ResourceNotFoundException("Assignment not found"));assignments.delete(a);}
}
